// Generates the judge facing reports in docs/ from the engine and from Base Sepolia receipts.
// Nothing in the generated files is typed in. Run: pnpm report
//
//   docs/EXECUTION_EVIDENCE.md   every transaction of a captured real run, checked against the chain
//   docs/RED_TEAM.md             the attack set, the benign set and the naive baseline, run now
//   docs/EVALUATION.md           every learned component's held out result, with docs/results/*.json
//
// The real run is read from evidence/real-run-<date>.sse, a saved copy of the /api/run stream in
// real mode. To make a new one: curl -N -H "x-zishi-demo: $DEMO_TOKEN" "$URL/api/run?scenario=fleet&fast=1" > evidence/real-run-<date>.sse

import { execSync } from "node:child_process";
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { runAll, runBenign, ATTACKS } from "../src/engine/attacks";
import { METRICS as GATE } from "../src/engine/ml/gate";
import { METRICS as PLAUS } from "../src/engine/ml/plausibility";
import { getEconomicsMetrics } from "../src/engine/economics";
import { run as ratchet } from "../src/engine/ratchet";
import { newState, update, score as creditScore, rateFor } from "../src/engine/credit/score";
import { evalDetection } from "../src/engine/drift/eval";
import { DEFAULT_POLICY } from "../src/engine/policy";
import type { ChainTx, EngineEvent } from "../src/engine/types";

const ROOT = join(__dirname, "..", "..");
const DOCS = join(ROOT, "docs");
const RPC = process.env.BASE_SEPOLIA_RPC || "https://sepolia.base.org";
const deployed = JSON.parse(readFileSync(join(ROOT, "contracts", "deployments", "base-sepolia.json"), "utf8")) as { block: number; deployer: string; contracts: Record<string, { address: string; tx: string; gasUsed: number }> };
const commit = (() => { try { return execSync("git rev-parse HEAD", { cwd: ROOT }).toString().trim(); } catch { return "unknown"; } })();
const stamp = new Date().toISOString();
const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
const yuan = (x: number) => `${Math.round(x).toLocaleString("en-US")} yuan`;
const short = (h: string) => `${h.slice(0, 10)}…${h.slice(-4)}`;
const explorerTx = (h: string) => `https://sepolia.basescan.org/tx/${h}`;

async function rpc<T>(method: string, params: unknown[]): Promise<T> {
  const res = await fetch(RPC, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }) });
  const j = (await res.json()) as { result?: T; error?: { message: string } };
  if (j.error) throw new Error(j.error.message);
  return j.result as T;
}

interface Receipt { status: string; blockNumber: string; gasUsed: number; to: string; logs: number }
async function receipt(hash: string): Promise<Receipt | null> {
  const r = await rpc<{ status: string; blockNumber: string; gasUsed: string; to: string; logs: unknown[] } | null>("eth_getTransactionReceipt", [hash]);
  if (!r) return null;
  return { status: r.status, blockNumber: r.blockNumber, gasUsed: parseInt(r.gasUsed, 16), to: r.to, logs: r.logs.length };
}

// The main table uses the first real capture (the one whose intent hashes were new on the Base
// IntentLog, so every intent is a contract call). Later captures are summarised in section 2b.
function captures(): string[] {
  const dir = join(__dirname, "..", "evidence");
  return readdirSync(dir).filter((f) => /^real-run-.*\.sse$/.test(f)).sort((a, b) => a.length - b.length || a.localeCompare(b));
}
function loadCapture(file: string): { file: string; events: EngineEvent[] } {
  const events = readFileSync(join(__dirname, "..", "evidence", file), "utf8").split("\n").filter((l) => l.startsWith("data: ")).map((l) => JSON.parse(l.slice(6)) as EngineEvent);
  return { file, events };
}
function latestCapture(): { file: string; events: EngineEvent[] } | null {
  const dir = join(__dirname, "..", "evidence");
  const files = captures();
  if (!files.length) return null;
  const file = files[0];
  const events = readFileSync(join(dir, file), "utf8").split("\n").filter((l) => l.startsWith("data: ")).map((l) => JSON.parse(l.slice(6)) as EngineEvent);
  return { file, events };
}

async function executionEvidence() {
  const cap = latestCapture();
  const out: string[] = [];
  out.push("# Execution evidence", "", `Generated by \`pnpm report\` (\`web/scripts/report.ts\`) at ${stamp} from commit \`${commit}\`. Do not edit by hand.`, "");
  out.push("Every row below is a real transaction on Base Sepolia (chain id 84532), fetched again from the chain while this file was written: status, block, gas and the receiving address come from the receipt, not from the engine. Amounts are demo units with no monetary value.", "");
  out.push("## 1. Contracts", "", `Deployed from \`${deployed.deployer}\` in block ${deployed.block.toLocaleString("en-US")}, source verified on Sourcify with an exact match.`, "", "| Contract | Address | Deploy transaction | Gas |", "|---|---|---|---|");
  for (const [name, c] of Object.entries(deployed.contracts)) out.push(`| ${name} | [${c.address}](https://sepolia.basescan.org/address/${c.address}) | [${short(c.tx)}](${explorerTx(c.tx)}) | ${c.gasUsed.toLocaleString("en-US")} |`);
  out.push("");
  if (!cap) { out.push("## 2. A real run", "", "No captured real run in `web/evidence`. See the header of this file for how to make one.", ""); return out.join("\n"); }
  // One row per hash, the last state the stream reported.
  const last = new Map<string, { tx: ChainTx; at: number; order: number }>();
  let order = 0; let intents = 0, decisions = 0, denies = 0, proofs = 0, holds = 0, gates = 0, refused = 0;
  for (const ev of cap.events) {
    if (ev.t === "chain") { const prev = last.get(ev.tx.hash); last.set(ev.tx.hash, { tx: ev.tx, at: ev.at, order: prev?.order ?? order++ }); }
    if (ev.t === "intent") intents++;
    if (ev.t === "policy") { decisions++; if (ev.decision.verdict === "deny") denies++; }
    if (ev.t === "proof") proofs++;
    if (ev.t === "telemetry" && !ev.ok) holds++;
    if (ev.t === "gate") { gates++; if (ev.action === "refuse" || ev.action === "hold") refused++; }
  }
  const rows = [...last.values()].sort((a, b) => a.order - b.order);
  const first = cap.events.find((e) => e.t === "chain");
  const t0 = first ? first.at : 0;
  out.push("## 2. A real run of the fleet scenario", "", `Captured from the public app in real mode (\`${cap.file}\`): ${cap.events.length} events, ${intents} signed intents, ${decisions} policy decisions (${denies} denied), ${gates} inbound messages through the gate (${refused} refused or held), ${holds} flight log held by the oracle, ${proofs} proof submitted, ${rows.length} transactions. ${(() => { const txs = [...new Map(cap.events.filter((e) => e.t === "chain").map((e) => [(e as { tx: ChainTx }).tx.hash, (e as { tx: ChainTx }).tx])).values()]; const commits = txs.filter((t) => t.label.startsWith("IntentLog.commit")).length; const repeats = txs.filter((t) => t.label.includes("already in the log")).length; return `Every intent hash goes to the deployed IntentLog before the policy engine decides: ${commits} were new commits by contract call${repeats ? `, ${repeats} were already in the log from an earlier run on the same key (intent hashes are deterministic for a seeded scenario), so the engine anchored them as calldata instead` : ""}. Every money event was anchored on the same chain with the event as calldata. `; })()}${(() => { const src = cap.events.map((e) => (e as { source?: string }).source).filter(Boolean); const m = src.filter((x) => x === "model").length; const tpl = src.filter((x) => x === "template").length; const fh = new Set(cap.events.filter((e) => e.t === "chain" && (e as { tx: ChainTx }).tx.fiscoHash).map((e) => (e as { tx: ChainTx }).tx.hash)).size; return `${m ? `${m} explanations were written by a free model on OpenRouter and passed the number check, ${tpl} are labelled template text (the free tier allows about ten model calls a minute).` : `No model key was set for this run, so all ${tpl} explanations are labelled template text; section 2b is a run with the free model on.`}${fh ? ` ${fh} intent commits carry a FISCO BCOS hash: the same intent hash went to the FISCO IntentLog in the same step.` : ""}`; })()}`, "");
  out.push("| # | Seconds | Event | Kind | Sent to | Status | Block | Gas | Events | Transaction |", "|---|---|---|---|---|---|---|---|---|---|");
  let gas = 0, ok = 0, commits = 0, missing = 0;
  for (const [i, r] of rows.entries()) {
    const rc = await receipt(r.tx.hash);
    await new Promise((res) => setTimeout(res, 120));
    const toName = rc ? (Object.entries(deployed.contracts).find(([, c]) => c.address.toLowerCase() === rc.to.toLowerCase())?.[0] ?? (rc.to.toLowerCase() === deployed.deployer.toLowerCase() ? "demo wallet (calldata anchor)" : rc.to)) : "not found";
    if (rc) { gas += rc.gasUsed; if (rc.status === "0x1") ok++; if (toName === "IntentLog") commits++; } else missing++;
    out.push(`| ${i + 1} | ${((r.at - t0) / 1000).toFixed(1)} | ${r.tx.label.replace(/\|/g, "/")} | ${r.tx.kind} | ${toName} | ${rc ? (rc.status === "0x1" ? "success" : "reverted") : "missing"} | ${rc ? parseInt(rc.blockNumber, 16).toLocaleString("en-US") : ""} | ${rc ? rc.gasUsed.toLocaleString("en-US") : ""} | ${rc ? rc.logs : ""} | [${short(r.tx.hash)}](${explorerTx(r.tx.hash)}) |`);
  }
  out.push("", `Checked ${rows.length} hashes against the chain: ${ok} succeeded, ${missing} not found, ${commits} were \`IntentLog.commit\` calls with a \`Committed\` event each, ${gas.toLocaleString("en-US")} gas in total (${(gas * 0.006e-9).toFixed(7)} ETH at 0.006 gwei).`, "");
  // Later real captures: the free model and the FISCO mirror switched on.
  for (const f of captures().slice(1)) {
    const c = loadCapture(f);
    const txs = [...new Map(c.events.filter((e) => e.t === "chain").map((e) => [(e as { tx: ChainTx }).tx.hash, (e as { tx: ChainTx }).tx])).values()];
    let ok = 0;
    for (const t of txs) { const r = await receipt(t.hash); if (r?.status === "0x1") ok += 1; }
    const src = c.events.map((e) => (e as { source?: string }).source).filter(Boolean);
    const m = src.filter((x) => x === "model").length, tpl = src.filter((x) => x === "template").length;
    const fh = txs.filter((t) => t.fiscoHash).length;
    out.push("## 2b. A second real run: free model and FISCO mirror on", "", `\`${f}\`, captured from the public app with the demo token after the free model and the FISCO target were switched on: ${c.events.length} events, ${txs.length} transactions, ${ok} of ${txs.length} receipts fetched again now with status success. ${m} explanations were written by a free model on OpenRouter and passed the number check, ${tpl} are labelled template text (about ten model calls a minute on the free tier). ${fh} intents carry a FISCO BCOS hash next to the Base one. The intent hashes were already in the Base IntentLog from the run above, so on Base they were anchored as calldata; \`pnpm verify:all\` re-checks every one of these receipts.`, "");
  }

  // One full job against the deployed contracts (contracts/script/fulljob.sh base): value moving
  // contract calls, kept apart from the calldata anchors above. Every receipt fetched again now.
  const fj = JSON.parse(readFileSync(join(ROOT, "contracts", "deployments", "base-sepolia-fulljob.json"), "utf8")) as { steps: { step: string; contract: string; function: string; from: string; valueWei: string; tx: string; block: number }[]; checks: { check: string; value: string }[]; contracts: Record<string, string> };
  const calls = fj.steps.filter((x) => /^\d+$/.test(x.step));
  let fjOk = 0;
  const fjRows: string[] = [];
  for (const x of calls) {
    const r = await receipt(x.tx);
    const ok = r?.status === "0x1";
    if (ok) fjOk += 1;
    fjRows.push(`| ${x.step} | ${x.contract}.${x.function} | ${x.from} | ${x.valueWei === "0" ? "0" : `${x.valueWei} wei`} | ${ok ? "success" : "FAILED"} | ${r ? parseInt(r.blockNumber, 16).toLocaleString("en-US") : "?"} | ${r?.gasUsed.toLocaleString("en-US") ?? "?"} | [\`${x.tx.slice(0, 10)}…${x.tx.slice(-4)}\`](${explorerTx(x.tx)}) |`);
  }
  out.push("## 3. One full job against the deployed contracts", "", `Run by \`contracts/script/fulljob.sh base\`: fresh keys for six roles, every step a call to the deployed Bond, Lease, JobBoard or IntentLog, value moving where the contract moves it. These are contract calls, not calldata anchors. ${fjOk} of ${calls.length} receipts fetched again now with status success. Amounts are a few gwei, enough to prove the flow at almost no cost.`, "", "| # | Call | From | Value | Status | Block | Gas | Transaction |", "|---|---|---|---|---|---|---|---|", ...fjRows, "", "What moved, read from balances at each transaction's block:", "", ...fj.checks.map((c) => `- ${c.check}: ${c.value}`), "", "The same job ran on FISCO BCOS, see `contracts/deployments/fisco-bcos.json` and `docs/FISCO_EVIDENCE.md`. The funding and sweep transfers for the role wallets are listed in `contracts/deployments/base-sepolia-fulljob.json`.", "");
  out.push("## 4. Reproduce", "", "```", "cd web && pnpm install", "pnpm test                       # 52 attacks blocked, 7 benign pass, every learned metric at or above its floor", "pnpm evidence && pnpm verify    # a simulated run and its balance sheet, every hash checked", "# real chain: a funded Base Sepolia key and the demo token in the environment, then", "JIXIN_REAL=1 pnpm evidence      # anchors on Base Sepolia", "pnpm report                     # rewrites this file from the latest capture and the chain", "```", "", "Any hash above can be checked on Basescan or with one RPC call:", "", "```", `curl -s ${RPC} -H 'content-type: application/json' -d '{"jsonrpc":"2.0","id":1,"method":"eth_getTransactionReceipt","params":["<hash>"]}'`, "```", "");
  out.push("## 5. What is simulated", "", "In the live engine the farmer, the pilot, the lender and the vendor are scripted actors with demo keys derived from public strings (demo only, anyone can derive them). Flight telemetry is synthetic. Inside the engine the Bond, JobBoard and Lease rules run in TypeScript mirrors of the deployed contracts and only IntentLog is called on chain; section 3 is the same flow run against the deployed contracts themselves. The public app runs in simulated mode and labels every hash; real mode needs the demo token. The captured run had no model key set, so every explanation in it is the labelled template text (source template); decisions never depend on the model. With a key the model rewords explanations and the ask the agent replies, checked against the facts.", "");
  return out.join("\n");
}

async function redTeam() {
  const results = await runAll();
  const benign = runBenign();
  const fell = results.filter((r) => r.naive === "fell").length;
  const blocked = results.filter((r) => r.blocked).length;
  const byLayer = new Map<string, { n: number; blocked: number }>();
  const byStd = new Map<string, { n: number; blocked: number }>();
  for (const r of results) {
    const l = byLayer.get(r.layer) ?? { n: 0, blocked: 0 }; l.n++; if (r.blocked) l.blocked++; byLayer.set(r.layer, l);
    const s = byStd.get(r.standard) ?? { n: 0, blocked: 0 }; s.n++; if (r.blocked) s.blocked++; byStd.set(r.standard, s);
  }
  const out: string[] = [];
  out.push("# Red team report", "", `Generated by \`pnpm report\` at ${stamp} from commit \`${commit}\`. Every case was run while this file was written; nothing is pasted.`, "");
  out.push(`${results.length} attack cases against the three layers (message gate, policy engine, contract mirrors), ${benign.total} ordinary farmer messages that must pass, and the same inputs through a naive wallet that reads addresses out of text and pays them.`, "");
  out.push("## Summary", "", "| | Result |", "|---|---|", `| Attacks blocked | ${blocked} of ${results.length} |`, `| Benign messages passed | ${benign.passed} of ${benign.total} |`, `| Naive wallet fell to | ${fell} of ${results.length} |`, "");
  out.push("| Layer | Cases | Blocked |", "|---|---|---|");
  for (const [l, v] of byLayer) out.push(`| ${l} | ${v.n} | ${v.blocked} |`);
  out.push("", "| Rubric item | Cases | Blocked |", "|---|---|---|");
  for (const [s, v] of byStd) out.push(`| ${s} | ${v.n} | ${v.blocked} |`);
  out.push("", "## Every case", "", "| # | Attack | Layer | Rubric item | Zishi | Naive wallet | What happened |", "|---|---|---|---|---|---|---|");
  for (const r of results) out.push(`| ${r.id} | ${r.name}${r.isolated ? " (isolated)" : ""} | ${r.layer} | ${r.standard} | ${r.blocked ? "blocked" : "NOT BLOCKED"} | ${r.naive === "fell" ? "paid the attacker" : "held"} | ${r.detail.replace(/\|/g, "/").replace(/\n/g, " ")} |`);
  out.push("", "## Benign set", "", "Ordinary requests that must pass the same gate. A gate that blocks these is useless to a farmer.", "");
  if (benign.failed.length) { out.push("| Message | Action | Reason |", "|---|---|---|"); for (const f of benign.failed) out.push(`| ${f.text} | ${f.action} | ${f.reason} |`); }
  else out.push(`All ${benign.total} passed.`);
  out.push("", "## How the layers are tested", "", "| Layer | Input | Blocked where |", "|---|---|---|", "| message | A message to the agent: injection, impersonation, a payee in the text, a fake lender notice, pressure | `framing.ts` rules plus the classifier in `ml/gate.ts`, before the agent reads it |", "| policy | A signed intent that breaks a rule: unknown payee, over cap, replay, wrong signer, a payee from message text | `policy.ts`, on the signed intent, before any mirror or contract moves money |", "| contract | A proof or a call that must revert: foreign evidence, stranger signature, a hunter on a live job, a second use of a proof | the mirrors in `contracts.ts`, with the same case in `contracts/test` |", "", `The cases live in \`web/src/engine/attacks.ts\` (${ATTACKS.length} entries). \`pnpm test\` fails if any attack passes or any benign message is held. The Evidence page in the app runs the same set at request time.`, "");
  return out.join("\n");
}

function evaluation(): { md: string; json: Record<string, unknown> } {
  const eco = getEconomicsMetrics();
  const r = ratchet(60);
  let st = newState(); const path = [creditScore(st).p];
  for (const o of ["confirmed", "confirmed", "confirmed", "held"] as const) { st = update(st, o); path.push(creditScore(st).p); }
  const credit = creditScore(st); const rate = rateFor(credit, DEFAULT_POLICY.rateBand);
  const drift = evalDetection();
  const json = {
    generatedAt: stamp, commit,
    classifier: GATE, oracle: PLAUS, economics: eco,
    ratchet: { baselineProfit: r.baselineProfit, bestProfit: r.bestProfit, steps: r.steps.length, kept: r.steps.filter((s) => s.kept).length, best: r.best, baseline: r.baseline, evalSeed: r.evalSeed, walkSeed: r.walkSeed },
    credit: { path, final: credit, rateBps: rate.rateBps },
    drift,
  };
  const out: string[] = [];
  out.push("# Evaluation of the learned and optimising components", "", `Generated by \`pnpm report\` at ${stamp} from commit \`${commit}\`. Every number is recomputed on its fixed seed; the raw values are in \`docs/results/\`. Charts of the same runs are in \`docs/charts/\`.`, "");
  out.push("All data is synthetic and says so: the message corpus is hand written, the flights are generated from physical rules with noise. Each component has a held out split chosen by a fixed seed before training, and the agent has no write path to the corpus, the seed or the threshold. None of these components signs, pays or changes a cap.", "");
  out.push("## 1. Message classifier (`ml/gate.ts`)", "", "Logistic regression on hashed character 1 to 3 grams, 2^14 buckets, trained at module load. It adds a risk score the rule gate can only turn into a hold.", "", "| Metric | Value |", "|---|---|", `| Training messages | ${GATE.trainN} |`, `| Held out messages | ${GATE.testN} |`, `| Accuracy | ${pct(GATE.accuracy)} |`, `| Precision | ${pct(GATE.precision)} |`, `| Recall | ${pct(GATE.recall)} |`, `| F1 | ${GATE.f1.toFixed(3)} |`, `| False alarm rate | ${pct(GATE.falseAlarmRate)} |`, `| Hold threshold | ${GATE.threshold} |`, `| Seed | ${GATE.seed} |`, "", `${GATE.heldOut}.`, "");
  out.push("## 2. Telemetry oracle (`ml/plausibility.ts`, `fusion/kalman.ts`, `fusion/conformal.ts`)", "", "Robust z over five features of a flight log, the GPS track smoothed by a Kalman filter with a Rauch Tung Striebel pass, the flag threshold set by split conformal calibration for a 2% false alarm target.", "", "| Metric | Value |", "|---|---|", `| Flights | ${PLAUS.n + PLAUS.trainN} generated, ${PLAUS.n} held out, ${PLAUS.tampered} of them tampered |`, `| Detection | ${pct(PLAUS.detectionRate)} |`, `| False alarm | ${pct(PLAUS.falseAlarmRate)} |`, `| Conformal threshold | z ${PLAUS.conformalThreshold.toFixed(2)} for a ${pct(PLAUS.targetFalseAlarm)} target, ${PLAUS.calibrationN} calibration flights |`, `| Coverage | ${pct(PLAUS.coverage)} |`, `| Raw track false alarm at matched detection | ${pct(PLAUS.rawFalseAlarmRate)} |`, `| Smoothed track false alarm at matched detection | ${pct(PLAUS.smoothedFalseAlarmRate)} |`, `| Seed | ${PLAUS.seed} |`, "", "| Tamper class | Flights | Caught |", "|---|---|---|");
  for (const [k, v] of Object.entries(PLAUS.byTamper)) out.push(`| ${k} | ${v.n} | ${v.caught} |`);
  out.push("", `${PLAUS.heldOut}.`, "");
  const m = eco.mdp, s = eco.stress;
  out.push("## 3. Lease strategy (`economics/mdp.ts`)", "", "A finite horizon Markov decision process over lease balance, bond, weather and offer class, solved by value iteration, compared with the greedy rule on the same seeded seasons with common random numbers.", "", "| Metric | Greedy rule | MDP policy |", "|---|---|---|", `| Mean season profit after instalments | ${yuan(m.comparison.greedy.meanProfit)} | ${yuan(m.comparison.mdp.meanProfit)} |`, `| Standard deviation | ${yuan(m.comparison.greedy.sd)} | ${yuan(m.comparison.mdp.sd)} |`, `| Seasons reaching title | ${pct(m.comparison.greedy.titleShare)} | ${pct(m.comparison.mdp.titleShare)} |`, "", `${m.states.toLocaleString("en-US")} states, ${m.horizon} weeks, ${m.seasons} seasons, seed ${m.seed}, advantage ${yuan(m.comparison.advantage)} a season.`, "");
  out.push("## 4. Bond stress test (`economics/stress.ts`)", "", "| Metric | Value |", "|---|---|", `| Seasons | ${s.seasons} |`, `| Default probability | ${pct(s.defaultProbability)} |`, `| Lender loss given default, mean, no bonds | ${yuan(s.lgdWithoutBonds.mean)} |`, `| Lender loss given default, p95, no bonds | ${yuan(s.lgdWithoutBonds.p95)} |`, `| Lender loss given default, mean, with bonds | ${yuan(s.lgdWithBonds.mean)} |`, `| Lender loss given default, p95, with bonds | ${yuan(s.lgdWithBonds.p95)} |`, `| Share of the p95 loss the bonds absorb | ${pct(s.bondCover)} |`, `| Expected vendor bond drawdown a season | ${yuan(s.expectedVendorDrawdown)} |`, `| Expected pilot slashes a season | ${yuan(s.expectedPilotSlashes)} |`, `| Seed | ${s.seed} |`, "");
  out.push("## 5. Strategy ratchet (`ratchet.ts`)", "", "| Metric | Value |", "|---|---|", `| Proposals | ${r.steps.length} |`, `| Kept | ${r.steps.filter((x) => x.kept).length} |`, `| Broke the reserve rule | ${r.steps.filter((x) => x.violation).length} |`, `| Profit on the frozen week, baseline | ${yuan(r.baselineProfit)} |`, `| Profit on the frozen week, best | ${yuan(r.bestProfit)} |`, `| Seeds | eval ${r.evalSeed}, walk ${r.walkSeed} |`, "");
  out.push("## 6. Pilot credit score (`credit/score.ts`)", "", `Buhlmann credibility on one fixed sequence: the fleet prior, three confirmed jobs, one held log. Score path ${path.map((p) => p.toFixed(3)).join(", ")}; final tier ${credit.tier}, instalment share ${rate.rateBps} bps inside the band.`, "");
  out.push("## 7. Drift monitor (`drift/cusum.ts`)", "", `One sided CUSUM on the classifier's risk score (target ${drift.params.target}, k ${drift.params.k}, h ${drift.params.h}). ${drift.note}.`, "");
  out.push("## 8. Second price planner (`planner.ts`, `economics/pricing.ts`)", "", `${eco.auction.note}.`, "");
  return { md: out.join("\n"), json };
}

async function main() {
  mkdirSync(join(DOCS, "results"), { recursive: true });
  const ev = await executionEvidence();
  writeFileSync(join(DOCS, "EXECUTION_EVIDENCE.md"), ev + "\n");
  console.log("wrote docs/EXECUTION_EVIDENCE.md");
  const rt = await redTeam();
  writeFileSync(join(DOCS, "RED_TEAM.md"), rt + "\n");
  console.log("wrote docs/RED_TEAM.md");
  const { md, json } = evaluation();
  writeFileSync(join(DOCS, "EVALUATION.md"), md + "\n");
  for (const [k, v] of Object.entries(json)) if (typeof v === "object") writeFileSync(join(DOCS, "results", `${k}.json`), JSON.stringify(v, null, 2) + "\n");
  console.log("wrote docs/EVALUATION.md and docs/results/*.json");
}

main().catch((e) => { console.error(e); process.exit(1); });
